// Spike: how Datacore and metadataCache expose inline candidate tags.
const body = (tag, other) => `# Spike heading #${tag}

Paragraph line one mentions evidence #${tag}
second line of same paragraph, no tag.

- list item with candidate #${tag}
  - child item without tag
- parent without tag
  - nested child with candidate #${tag}
- [ ] task with candidate #${tag}
- item with two tags #${other} #${tag}

> quoted candidate #${tag}

Plain paragraph without tag.
`;

export default {
  name: "Datacore tag spike",
  input: "query tagged lines via datacore + metadataCache",
  expected: "report",
  run: async ({ client, json, vault, writeNote }) => {
    const info = await client.evaluate(`
      const p = app.plugins.plugins[${json(vault.pluginId)}];
      return {
        datacore: !!app.plugins.plugins["datacore"],
        dcVersion: app.plugins.manifests["datacore"]?.version,
        tags: p.settings.nodeTypes.map(n => ({ name: n.name, tag: n.tag })),
      };`);
    const tag = info.tags.find((t) => t.tag)?.tag;
    const other = info.tags.filter((t) => t.tag)[1]?.tag ?? "someothertag";
    const path = await writeNote("datacore-spike.md", body(tag, other));
    const rel = path.replace(vault.root + "/", "");
    await client.waitFor(`(app.metadataCache.getCache(${json(rel)})?.tags?.length ?? 0) >= 7`, 10000);
    // give datacore time to index the new file
    await client.evaluate(`return new Promise(r => setTimeout(r, 2000))`);
    const report = await client.evaluate(`
      const dc = app.plugins.plugins["datacore"]?.api;
      const rel = ${json(rel)};
      const tag = ${json(tag)};
      const out = { tag, rel, cacheTags: app.metadataCache.getCache(rel)?.tags?.map(t => ({ tag: t.tag, line: t.position.start.line })) };
      if (!dc) return out;
      const pick = (o) => ({ type: o.$type, line: o.$line, lineCount: o.$lineCount, tags: o.$tags, text: o.$text, keys: Object.keys(o).filter(k => k.startsWith("$")) });
      const run = (q) => { try { const r = dc.query(q); return r.filter(o => (o.$file ?? o.$path) === rel || (o.$file ?? "").endsWith(rel)).map(pick); } catch (e) { return "ERR " + e.message; } };
      out.queries = {
        block: run("@block and #" + tag),
        listItem: run("@list-item and #" + tag),
        task: run("@task and #" + tag),
        section: run("@section and #" + tag),
        page: run("@page and #" + tag).length,
        orTags: run("(@block or @list-item) and (#" + tag + " or #nonexistent-xyz)").length,
      };
      return out;`);
    return { info, report };
  },
  expect: (actual) => ({ pass: true, actual: JSON.stringify(actual, null, 1) }),
};

