  onOpenChange,
  onShowCandidatesChange,
  showCandidates,
}: {
  app: App;
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  onShowCandidatesChange: (showCandidates: boolean) => void;
