// ENG-2272 candidate nodes in advanced node search.
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;
const ROWS = `${MODAL} [role="option"]`;

const nodeTypes = ({ client, json, vault }) =>
  client.evaluate(`return app.plugins.plugins[${json(vault.pluginId)}].settings.nodeTypes
    .map((n) => ({ id: n.id, name: n.name, tag: n.tag }));`);

const seed = async (ctx) => {
  const types = await nodeTypes(ctx);
  const claim = types.find((t) => t.tag === "clm-candidate");
  const evidence = types.find((t) => t.tag === "evd-candidate");
  const notePath = await ctx.writeNote(
    "zephyr-candidates.md",
    [
      "Intro paragraph about zephyr winds",
      "Zephyr winds cool the coast #clm-candidate",
      "- Zephyr gauge readings rose 4% #evd-candidate",
      "## Zephyr heading claim #clm-candidate",
    ].join("\n"),
  );
  const nodePath = await ctx.writeNote(
    "CLM - Zephyr node claim.md",
    `---\nnodeTypeId: ${claim.id}\n---\nBody\n`,
  );
  const rel = (p) => p.replace(ctx.vault.root + "/", "");
  await ctx.client.waitFor(
    `(app.metadataCache.getCache(${ctx.json(rel(notePath))})?.tags?.length ?? 0) >= 3 &&
     !!app.metadataCache.getCache(${ctx.json(rel(nodePath))})?.frontmatter?.nodeTypeId`,
    { timeout: 10000, label: "seed notes indexed" },
  );
  return { claim, evidence, noteRel: rel(notePath) };
};

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input" });
};

const typeQuery = async ({ client, json }, text) => {
  await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
  await client.typeText(text);
};

const toggleCandidates = async ({ client, json }) => {
  await client.evaluate(`document.querySelector(${json(`${MODAL} button[aria-label="Display options"]`)}).click(); return true;`);
  await client.waitFor(`!!document.querySelector(${json(`${MODAL} [role="menuitemcheckbox"]`)})`, { label: "display menu" });
  await client.evaluate(`document.querySelector(${json(`${MODAL} [role="menuitemcheckbox"]`)}).click(); return true;`);
};

const readRows = ({ client, json }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(${json(ROWS)})).map((row) => {
    const title = row.querySelector(".dg-search-result-title");
    const pill = row.querySelector("span[aria-label]");
    const pillStyle = pill ? getComputedStyle(pill) : null;
    return {
      title: title?.textContent,
      titleX: Math.round(title?.getBoundingClientRect().left ?? -1),
      pillX: Math.round(pill?.getBoundingClientRect().left ?? -1),
      pillW: Math.round(pill?.getBoundingClientRect().width ?? -1),
      pillLabel: pill?.getAttribute("aria-label"),
      pillBg: pillStyle?.backgroundColor,
      subtitle: row.querySelector(".text-xs.text-muted")?.textContent ?? null,
    };
  });`);

const waitForRows = ({ client, json }, predicate, label) =>
  client.waitFor(`(() => { const t = Array.from(document.querySelectorAll(${json(ROWS)}))
    .map((r) => r.querySelector(".dg-search-result-title")?.textContent ?? ""); return ${predicate}; })()`,
    { timeout: 5000, label });

export default [
  {
    name: "Toggle off hides candidates, on shows them",
    input: "query 'zephyr'; read rows; toggle Show candidate nodes; read rows",
    expected: "off: only the node; on: node + 3 candidate lines, each titled by its own line",
    setup: seed,
    run: async (ctx) => {
      await openSearch(ctx);
      await typeQuery(ctx, "zephyr");
      await waitForRows(ctx, `t.includes("CLM - Zephyr node claim")`, "node row");
      const off = (await readRows(ctx)).map((r) => r.title);
      await toggleCandidates(ctx);
      await waitForRows(ctx, `t.includes("Zephyr winds cool the coast")`, "candidate rows");
      const on = await readRows(ctx);
      return { off, on };
    },
    expect: ({ off, on }) => {
      const titles = on.map((r) => r.title);
      const want = ["Zephyr winds cool the coast", "Zephyr gauge readings rose 4%", "Zephyr heading claim"];
      const pass =
        !off.some((t) => want.includes(t)) &&
        want.every((t) => titles.includes(t)) &&
        titles.includes("CLM - Zephyr node claim") &&
        !titles.includes("Intro paragraph about zephyr winds");
      return { pass, actual: `off=${JSON.stringify(off)} on=${JSON.stringify(on.map((r) => [r.title, r.subtitle]))}` };
    },
  },
  {
    name: "Badges and titles are flush; candidates outlined",
    input: "toggle on, empty query; measure every row's pill x/width and title x",
    expected: "one title x and one pill x/width across all rows; candidate pills transparent, node pills filled",
    run: async (ctx) => {
      await openSearch(ctx);
      await toggleCandidates(ctx);
      await typeQuery(ctx, "zephyr");
      await waitForRows(ctx, `t.includes("Zephyr winds cool the coast")`, "candidate rows");
      return readRows(ctx);
    },
    expect: (rows) => {
      const uniq = (xs) => [...new Set(xs)];
      const withPill = rows.filter((r) => r.pillX >= 0);
      const titleXs = uniq(rows.map((r) => r.titleX));
      const pillXs = uniq(withPill.map((r) => r.pillX));
      const pillWs = uniq(withPill.map((r) => r.pillW));
      const candidates = withPill.filter((r) => r.pillLabel?.endsWith("candidate"));
      const nodes = withPill.filter((r) => !r.pillLabel?.endsWith("candidate"));
      const outlined = candidates.every((r) => r.pillBg === "rgba(0, 0, 0, 0)");
      const filled = nodes.every((r) => r.pillBg !== "rgba(0, 0, 0, 0)");
      const pass = titleXs.length === 1 && pillXs.length === 1 && pillWs.length === 1 && outlined && filled && candidates.length >= 3;
      return { pass, actual: `rows=${rows.length} titleX=${titleXs} pillX=${pillXs} pillW=${pillWs} candidates=${candidates.length} outlined=${outlined} nodesFilled=${filled}` };
    },
  },
  {
    name: "Type filter applies to candidates",
    input: "toggle on, query 'zephyr', filter to Evidence only",
    expected: "only the evidence candidate remains",
    setup: seed,
    run: async (ctx, { evidence }) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await toggleCandidates(ctx);
      await typeQuery(ctx, "zephyr");
      await waitForRows(ctx, `t.includes("Zephyr winds cool the coast")`, "candidate rows");
      await client.evaluate(`document.querySelector(${json(`${MODAL} button[title="Filter by type"]`)}).click(); return true;`);
      await client.evaluate(`const label = Array.from(document.querySelectorAll(${json(`${MODAL} label`)}))
        .find((l) => l.textContent.trim() === ${json(evidence.name)});
        label.querySelector("input").click(); return true;`);
      await waitForRows(ctx, `!t.includes("Zephyr winds cool the coast")`, "claim filtered out");
      return (await readRows(ctx)).map((r) => r.title);
    },
    expect: (titles) => ({
      pass: titles.length === 1 && titles[0] === "Zephyr gauge readings rose 4%",
      actual: JSON.stringify(titles),
    }),
  },
  {
    name: "Enter on a candidate opens its line",
    input: "toggle on, query 'coast', Enter",
    expected: "zephyr-candidates.md opens in a new tab with the cursor on line 2 (index 1)",
    setup: seed,
    run: async (ctx, { noteRel }) => {
      const { client } = ctx;
      await openSearch(ctx);
      await toggleCandidates(ctx);
      await typeQuery(ctx, "cool the coast");
      await waitForRows(ctx, `t[0] === "Zephyr winds cool the coast"`, "candidate first");
      await client.key("Enter");
      await client.waitFor(`app.workspace.getActiveFile()?.path === ${ctx.json(noteRel)}`, { timeout: 5000, label: "file opened" });
      return client.evaluate(`return { path: app.workspace.getActiveFile()?.path,
        line: app.workspace.activeEditor?.editor?.getCursor().line,
        modalOpen: !!document.querySelector(${ctx.json(MODAL)}) };`);
    },
    expect: (actual, { noteRel }) => ({
      pass: actual.path === noteRel && actual.line === 1 && !actual.modalOpen,
      actual: JSON.stringify(actual),
    }),
  },
];

